#!/bin/bash
# Generated by governance model version 3. Only the generator changes this file.
#
# The owner script: habit runs it as the maintainer account, never an agent, to apply this
# repository's GitHub target state. Run it only from the owner-script command a session hands
# over, which runs origin's default-branch copy from a temporary detached checkout with the
# maintainer account's own gh configuration. It stops, writing nothing, unless that copy is
# the default branch's head and gh acts as the repository's owner. It reads the record through
# the gate script beside it and declares the target state, so a rerun at target state writes
# nothing. It reports each item in Chinese and prints no credential.
set -eu
here="$(cd "$(dirname "$0")" && pwd)"
exec /usr/bin/python3 -I - "$here" "$@" <<'PY'
"""The owner script's program: preconditions, then the target state, declared.

1. Preconditions, before any write: no token variable overrides the gh configuration; the
   copy is a clean checkout at the default branch's head on GitHub; gh acts as the
   repository's owner, with admin; the record parses through the gate script's parser; and
   Actions can run the gate's workflow. Any failure stops the run with exit code 2.
2. Rulesets: Gate, Merge and History, created, or updated in place from the first branch
   ruleset of that name on the default branch; a name held only by a ruleset elsewhere fails
   that item and leaves the holder alone. Only once all three are in place is every other
   ruleset that applies to the default branch, by GitHub's fnmatch reading of its patterns,
   removed and named, and classic branch protection on it with them. Rulesets on other
   branches and tags stay and are listed; a ruleset whose pattern has a form GitHub doesn't
   support stays and fails with the reason.
3. Settings: squash merge only, head branches deleted on merge, auto-merge off, and Actions
   unable to create or approve pull requests.
4. A public repository gets secret scanning and push protection, and the Actions event
   policy that allows pull_request_target for the gate's workflow only. A private repository
   skips both, and the report says why.

Each item compares GitHub's state with what the target declares and writes only what
differs. A write that answers with the written object is confirmed from it; a DELETE, and
the Actions setting's PUT, answer with no content and count on success. Exit codes: 0 when
every item is in place, 1 when an item failed or is missing, or GitHub failed after a
write; 2 when the run stopped before any write.
"""

import json
import os
import re
import subprocess
import sys
import time
from urllib.parse import quote

sys.dont_write_bytecode = True
GOVERNANCE = sys.argv[1]
sys.path.insert(0, GOVERNANCE)

import gate  # noqa: E402

# The GitHub Actions app: GET /apps/github-actions returns this id (read 2026-10-28).
ACTIONS_APP = 15368
# A ruleset's bypass actor for the repository admin role.
ADMIN_ROLE = 5
GATE_WORKFLOW = ".github/workflows/governance-gate.yml"
# The gate workflow's one action, which a restricted Actions policy must still allow.
CHECKOUT = "actions/checkout"
_USES_CHECKOUT = re.compile(r"(?m)^ +(?:- )?uses: (actions/checkout@\S+)")
TOKEN_VARIABLES = ("GH_TOKEN", "GITHUB_TOKEN", "GH_ENTERPRISE_TOKEN", "GITHUB_ENTERPRISE_TOKEN")
RULESET_NAMES = ("Gate", "Merge", "History")
OURS = "、".join(RULESET_NAMES)
_REMOTE = re.compile(r"(?:https://github\.com/|git@github\.com:|ssh://git@github\.com/)([A-Za-z0-9-]+/[A-Za-z0-9._-]+?)(?:\.git)?/?")
_HTTP_STATUS = re.compile(r"\(HTTP (\d{3})\)")


class Stop(Exception):
    """A precondition failed: the run stops before writing, and the message says why."""


class GitHubError(Exception):
    def __init__(self, status, message):
        super(GitHubError, self).__init__(message)
        self.status, self.message = status, message


# Talking to GitHub and git.


def gh_api(path, method="GET", body=None, timeout=None):
    """The parsed JSON of one `gh api` call, None for an empty response, or GitHubError."""
    args = ["gh", "api"]
    if method != "GET":
        args += ["--method", method]
    args.append(path)
    data = None
    if body is not None:
        args += ["--input", "-"]
        data = json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
    try:
        result = subprocess.run(args, input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise GitHubError(None, "gh 读取超时")
    except OSError as error:
        raise GitHubError(None, "gh 无法运行：%s" % error)
    out = result.stdout.decode("utf-8", "replace")
    if result.returncode != 0:
        err = result.stderr.decode("utf-8", "replace")
        status = _HTTP_STATUS.search(err)
        message = ""
        try:
            message = json.loads(out).get("message", "")
        except (ValueError, AttributeError):
            pass
        raise GitHubError(int(status.group(1)) if status else None, message or " ".join(err.split()) or "gh 失败")
    if not out.strip():
        return None
    try:
        return json.loads(out)
    except ValueError:
        raise GitHubError(None, "gh 的输出不是 JSON")


def git(root, *args):
    result = subprocess.run(["git", "-C", root] + list(args), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode != 0:
        raise Stop("`git %s` 失败：%s" % (" ".join(args), " ".join(result.stderr.decode("utf-8", "replace").split())))
    return result.stdout.decode("utf-8").strip()


# The report: one line per item, `[状态] 项目：详情`, under `== 节` headings.


class Report(object):
    def __init__(self):
        self.writes, self.problems, self.current = 0, 0, ""

    def section(self, title):
        self.current = title
        print("== %s" % title)

    def line(self, status, subject, detail):
        if status in ("未通过", "缺失"):
            self.problems += 1
        print("[%s] %s：%s" % (status, subject, detail))
        sys.stdout.flush()

    def wrote(self, status, subject, detail):
        self.writes += 1
        self.line(status, subject, detail)


# 1. Preconditions.


def preconditions(report):
    """The repository's facts once every precondition passes; Stop otherwise."""
    report.section("前提")
    present = [name for name in TOKEN_VARIABLES if os.environ.get(name)]
    if present:
        raise Stop("设置了 %s，它会盖过 gh 配置；请从 owner-script command 运行，它不带 token 变量" % "、".join(present))
    try:
        root = git(GOVERNANCE, "rev-parse", "--show-toplevel")
    except Stop:
        raise Stop("%s 不在 git 副本中；请从 owner-script command 运行" % GOVERNANCE)
    match = _REMOTE.fullmatch(git(root, "config", "--get", "remote.origin.url"))
    if not match:
        raise Stop("副本的 origin 不是 GitHub 仓库")
    repository = match.group(1)

    login = gh_api("user")["login"]
    try:
        repo = gh_api("repos/%s" % repository)
    except GitHubError as error:
        raise Stop("%s 读不到 %s：%s" % (login, repository, error.message))
    repository, owner, branch = repo["full_name"], repo["owner"]["login"], repo["default_branch"]
    admin = (repo.get("permissions") or {}).get("admin") is True
    if login.lower() != owner.lower() or not admin:
        raise Stop(
            "gh 当前账户是 %s，不是 %s 的所有者 %s；请用 maintainer 账户自己的 gh 配置运行，不能用 ghm"
            % (login, repository, owner)
        )
    config = os.environ.get("GH_CONFIG_DIR") or "gh 的默认配置"
    home = os.environ.get("HOME")
    if home and config.startswith(home + os.sep):
        config = "~" + config[len(home):]
    report.line("通过", "账户", "gh 以所有者 %s 身份操作 %s（gh 配置：%s）" % (login, repository, config))

    head = git(root, "rev-parse", "HEAD")
    default_head = gh_api("repos/%s/branches/%s" % (repository, quote(branch, safe="")))["commit"]["sha"]
    if head != default_head:
        raise Stop("副本在 %s，不是 %s 的 %s 最新提交 %s；请从 owner-script command 运行" % (head[:12], repository, branch, default_head[:12]))
    if git(root, "status", "--porcelain", "--untracked-files=no"):
        raise Stop("副本有未提交的改动，不是 %s 最新提交的原样；请从 owner-script command 运行" % branch)
    report.line("通过", "副本", "%s 是 %s 的最新提交，且无改动" % (head[:12], branch))

    try:
        with open(os.path.join(root, *gate.RECORD.split("/")), "rb") as handle:
            record = gate.parse_record(handle.read())
    except (OSError, gate.RecordError) as error:
        raise Stop("%s 无法解析：%s" % (gate.RECORD, error))
    checks = required_checks(record)
    report.line("通过", "记录", "%s 可解析；必需检查：%s" % (gate.RECORD, describe_checks(checks)))

    actions_can_run(report, repository, root)
    return {"root": root, "repository": repository, "branch": branch, "repo": repo, "checks": checks}


def actions_can_run(report, repository, root):
    """Stop unless Actions is enabled and allows the checkout action the gate workflow pins."""
    permissions = gh_api("repos/%s/actions/permissions" % repository)
    if not permissions.get("enabled"):
        raise Stop("此仓库的 Actions 已停用，governance-gate 永远不会报告；请在 Settings → Actions → General 允许 Actions 后重新运行")
    allowed = permissions.get("allowed_actions")
    if allowed == "selected":
        try:
            with open(os.path.join(root, *GATE_WORKFLOW.split("/")), encoding="utf-8") as handle:
                pinned = _USES_CHECKOUT.findall(handle.read())
        except OSError:
            pinned = []
        selected = gh_api("repos/%s/actions/permissions/selected-actions" % repository)
        patterns = selected.get("patterns_allowed") or []
        allowed_checkout = selected.get("github_owned_allowed") is True or bool(pinned) and all(
            any(re.fullmatch(".*".join(re.escape(piece) for piece in pattern.split("*")), uses) for pattern in patterns)
            for uses in pinned
        )
        if not allowed_checkout:
            raise Stop("此仓库的 Actions 只允许选定的 action，不含 %s，governance-gate 无法运行；请在 Settings → Actions → General 允许 GitHub 自己的 action 后重新运行" % CHECKOUT)
    elif allowed != "all":
        raise Stop("此仓库的 Actions 只允许本仓库内的 action，governance-gate 用的 %s 无法运行；请在 Settings → Actions → General 放开后重新运行" % CHECKOUT)
    report.line("已就位", "Actions 可运行工作流", "Actions 已启用，允许 governance-gate 用的 %s" % CHECKOUT)


def required_checks(record):
    checks = [{"context": gate.CHECK, "integration_id": ACTIONS_APP}]
    for name in record["confirmed"]["required_checks"]:
        if name not in [check["context"] for check in checks]:
            checks.append({"context": name})
    return checks


def describe_checks(checks):
    return "、".join(
        "%s（仅 GitHub Actions）" % check["context"] if check.get("integration_id") else check["context"] for check in checks
    )


# 2. Rulesets.


def target_rulesets(checks):
    """#41 §7's three rulesets, as the bodies sent to GitHub."""
    admin = [{"actor_id": ADMIN_ROLE, "actor_type": "RepositoryRole", "bypass_mode": "always"}]

    def branches(include):
        return {"ref_name": {"include": [include], "exclude": []}}

    pull_request = {
        "allowed_merge_methods": ["squash"],
        "dismiss_stale_reviews_on_push": False,
        "require_code_owner_review": False,
        "require_last_push_approval": False,
        "required_approving_review_count": 0,
        "required_review_thread_resolution": False,
    }
    status_checks = {
        "do_not_enforce_on_create": False,
        "required_status_checks": checks,
        "strict_required_status_checks_policy": False,
    }
    return [
        {
            "name": "Gate",
            "target": "branch",
            "enforcement": "active",
            "bypass_actors": [],
            "conditions": branches("~DEFAULT_BRANCH"),
            "rules": [
                {"type": "deletion"},
                {"type": "non_fast_forward"},
                {"type": "pull_request", "parameters": pull_request},
                {"type": "required_status_checks", "parameters": status_checks},
            ],
        },
        {
            "name": "Merge",
            "target": "branch",
            "enforcement": "active",
            "bypass_actors": admin,
            "conditions": branches("~DEFAULT_BRANCH"),
            "rules": [{"type": "update", "parameters": {"update_allows_fetch_and_merge": False}}],
        },
        {
            "name": "History",
            "target": "branch",
            "enforcement": "active",
            "bypass_actors": admin,
            "conditions": branches("~ALL"),
            "rules": [{"type": "non_fast_forward"}],
        },
    ]


RULESET_SUMMARY = {
    "Gate": "默认分支；无人可绕过；禁止删除和 force-push；须经 PR（0 个批准，仅 squash）；必需检查 %s，不要求分支最新",
    "Merge": "默认分支；仓库管理员始终可绕过；限制更新",
    "History": "所有分支；仓库管理员始终可绕过；禁止 force-push",
}

def _sorted_json(items):
    return sorted(json.dumps(item, sort_keys=True) for item in items)


def declared(ruleset):
    """What the target state declares about a ruleset, read from a body or from GitHub's response.

    GitHub returns fields and parameters the body never sent, in its own order. Only the
    declared ones count, lists compare as sets, and a missing boolean reads as false, so a
    rerun at target state finds every ruleset equal and writes nothing.
    """
    rules = {}
    for rule in ruleset.get("rules") or []:
        parameters = rule.get("parameters") or {}
        if rule["type"] == "pull_request":
            known = ("dismiss_stale_reviews_on_push", "require_code_owner_review", "require_last_push_approval",
                     "required_review_thread_resolution")
            value = dict((key, parameters.get(key, False)) for key in known)
            value["required_approving_review_count"] = parameters.get("required_approving_review_count", 0)
            value["allowed_merge_methods"] = sorted(parameters.get("allowed_merge_methods") or ["merge", "rebase", "squash"])
        elif rule["type"] == "required_status_checks":
            value = dict((key, parameters.get(key, False))
                         for key in ("do_not_enforce_on_create", "strict_required_status_checks_policy"))
            value["required_status_checks"] = _sorted_json(
                {"context": check["context"], "integration_id": check.get("integration_id")}
                for check in parameters.get("required_status_checks") or []
            )
        elif rule["type"] == "update":
            value = {"update_allows_fetch_and_merge": parameters.get("update_allows_fetch_and_merge", False)}
        else:
            value = parameters
        rules[rule["type"]] = value
    ref_name = (ruleset.get("conditions") or {}).get("ref_name") or {}
    return {
        "name": ruleset.get("name"),
        "target": ruleset.get("target"),
        "enforcement": ruleset.get("enforcement"),
        "bypass_actors": _sorted_json(
            {"actor_id": actor.get("actor_id"), "actor_type": actor.get("actor_type"), "bypass_mode": actor.get("bypass_mode")}
            for actor in ruleset.get("bypass_actors") or []
        ),
        "include": sorted(ref_name.get("include") or []),
        "exclude": sorted(ref_name.get("exclude") or []),
        "rules": rules,
    }


# Ref patterns: a port of Ruby's File.fnmatch with FNM_PATHNAME (dir.c's fnmatch,
# fnmatch_helper and bracket), the reading GitHub documents for ruleset patterns. A translation
# into a regular expression misread character sets twice, so this follows Ruby step by step;
# tests/fixtures/owner/ref-patterns.json holds Ruby's own answers.
# GitHub refuses a backslash and doesn't support complementing a set with `^`, so a pattern
# with either has no known reading there.
UNREADABLE_FORMS = ("\\", "[^")


def _bracket(p, i, ch):
    """Ruby's bracket(): where the set opened just before p[i] ends if it admits ch, else None."""
    ok = negated = False
    if i < len(p) and p[i] in "!^":
        negated, i = True, i + 1
    while True:
        if i >= len(p):
            return None
        if p[i] == "]":
            break
        t1 = i + 1 if p[i] == "\\" else i
        if t1 >= len(p):
            return None
        i = t1 + 1
        if i >= len(p):
            return None
        if p[i] == "-" and (i + 1 >= len(p) or p[i + 1] != "]"):
            t2 = i + 2 if i + 1 < len(p) and p[i + 1] == "\\" else i + 1
            if t2 >= len(p):
                return None
            i = t2 + 1
            # Ruby admits either end before comparing the range, so a reversed range keeps both ends.
            ok = ok or ch in (p[t1], p[t2]) or p[t1] <= ch <= p[t2]
            continue
        ok = ok or p[t1] == ch
    return None if ok == negated else i + 1


def _component(p, pi, s, si):
    """Ruby's fnmatch_helper(): match one path component; (matched, pattern index, string index)."""
    def end(text, i):
        return i >= len(text) or text[i] == "/"

    def unescape(i):
        return i + 1 if i < len(p) and p[i] == "\\" else i

    if si < len(s) and s[si] == "." and (p[unescape(pi)] if unescape(pi) < len(p) else "") != ".":
        return False, pi, si
    ptmp = stmp = None
    while True:
        c = p[pi] if pi < len(p) else ""
        if c == "*":
            while pi < len(p) and p[pi] == "*":
                pi += 1
            if end(p, unescape(pi)):
                return True, unescape(pi), si
            if end(s, si):
                return False, pi, si
            ptmp, stmp = pi, si
            continue
        if c == "?":
            if end(s, si):
                return False, pi, si
            pi, si = pi + 1, si + 1
            continue
        if c == "[":
            if end(s, si):
                return False, pi, si
            after = _bracket(p, pi + 1, s[si])
            if after is not None:
                pi, si = after, si + 1
                continue
        else:
            pi = unescape(pi)
            if end(s, si):
                return end(p, pi), pi, si
            if not end(p, pi) and p[pi] == s[si]:
                pi, si = pi + 1, si + 1
                continue
        if ptmp is None:
            return False, pi, si
        stmp += 1
        pi, si = ptmp, stmp


def fnmatch(p, s):
    """Ruby's File.fnmatch(p, s, File::FNM_PATHNAME)."""
    pi = si = 0
    ptmp = stmp = None
    while True:
        if p.startswith("**/", pi):
            while p.startswith("**/", pi):
                pi += 3
            ptmp, stmp = pi, si
        matched, pi, si = _component(p, pi, s, si)
        if matched:
            while si < len(s) and s[si] != "/":
                si += 1
            if pi < len(p) and si < len(s):
                pi, si = pi + 1, si + 1
                continue
            if pi >= len(p) and si >= len(s):
                return True
        if ptmp is not None and not (stmp < len(s) and s[stmp] == "."):
            while stmp < len(s) and s[stmp] != "/":
                stmp += 1
            if stmp < len(s):
                stmp += 1
                pi, si = ptmp, stmp
                continue
        return False


def applies_to(ruleset, branch):
    """Whether a ruleset applies to the default branch, enforced or not: True, False, or None
    when a branch ruleset's pattern has a form GitHub doesn't support, so nobody can tell."""
    if ruleset.get("target") != "branch":
        return False
    ref_name = (ruleset.get("conditions") or {}).get("ref_name") or {}
    include, exclude = ref_name.get("include") or [], ref_name.get("exclude") or []
    if any(form in pattern for pattern in include + exclude for form in UNREADABLE_FORMS):
        return None

    def hit(pattern):
        if pattern in ("~ALL", "~DEFAULT_BRANCH"):
            return True
        return fnmatch(pattern if pattern.startswith("refs/") else "refs/heads/" + pattern, "refs/heads/" + branch)

    return any(hit(p) for p in include) and not any(hit(p) for p in exclude)


def describe_ruleset(ruleset):
    return "“%s”（id %s，%s）" % (ruleset.get("name"), ruleset.get("id"), ruleset.get("target"))


def read_rulesets(repository):
    try:
        listed = gh_api("repos/%s/rulesets?includes_parents=false&per_page=100" % repository)
    except GitHubError as error:
        raise Stop("读不到 %s 的规则集（%s）；私有仓库需要所有者的 GitHub Pro" % (repository, error.message))
    try:
        return [gh_api("repos/%s/rulesets/%s" % (repository, item["id"])) for item in listed or []]
    except GitHubError as error:
        raise Stop("读不到 %s 的某个规则集：%s" % (repository, error.message))


def apply_rulesets(report, facts):
    report.section("规则集")
    repository, branch = facts["repository"], facts["branch"]
    existing = read_rulesets(repository)
    # One of the three is the first ruleset of its name on the default branch; any other
    # ruleset, a same-named one elsewhere included, is judged with the rest below.
    by_name = {}
    for ruleset in existing:
        if ruleset.get("name") in RULESET_NAMES and applies_to(ruleset, branch) is True:
            by_name.setdefault(ruleset.get("name"), ruleset)
    adopted = set(ruleset["id"] for ruleset in by_name.values())
    taken = dict((ruleset.get("name"), ruleset) for ruleset in existing if ruleset["id"] not in adopted)
    ours_in_place = True
    for body in target_rulesets(facts["checks"]):
        name = body["name"]
        summary = RULESET_SUMMARY[name] % describe_checks(facts["checks"]) if name == "Gate" else RULESET_SUMMARY[name]
        current = by_name.get(name)
        if current is None and name in taken:
            ours_in_place = False
            report.line("未通过", "%s 规则集" % name, "规则集 %s 已占用这个名字，但不是确定作用于默认分支 %s 的分支规则集，未改动它；"
                        "请把它改名后重跑" % (describe_ruleset(taken[name]), branch))
            continue
        if current is not None and declared(current) == declared(body):
            report.line("已就位", "%s 规则集" % name, summary)
            continue
        try:
            if current is None:
                written = gh_api("repos/%s/rulesets" % repository, "POST", body)
            else:
                written = gh_api("repos/%s/rulesets/%s" % (repository, current["id"]), "PUT", body)
        except GitHubError as error:
            ours_in_place = False
            report.line("未通过", "%s 规则集" % name, "GitHub 拒绝了写入：%s" % error.message)
            continue
        if declared(written or {}) != declared(body):
            ours_in_place = False
            report.line("未通过", "%s 规则集" % name, "GitHub 的回应与目标不一致")
            continue
        report.wrote("已设置", "%s 规则集" % name, ("已创建：" if current is None else "已更新：") + summary)

    others = [ruleset for ruleset in existing if ruleset["id"] not in adopted]
    for ruleset in others:
        applies = applies_to(ruleset, branch)
        if applies is None:
            report.line("未通过", "规则集 %s" % describe_ruleset(ruleset),
                        "它的分支模式含 GitHub 不支持的写法（反斜杠或 [^），判断不了是否作用于默认分支 %s，保留不动；"
                        "请在 GitHub 上核对它并改写模式后重跑" % branch)
        elif not applies:
            report.line("已保留", "规则集 %s" % describe_ruleset(ruleset), "不作用于默认分支 %s，保留不动" % branch)
        elif not ours_in_place:
            report.line("已跳过", "规则集 %s" % describe_ruleset(ruleset), "%s 未全部就位，先不移除默认分支上的保护" % OURS)
        else:
            try:
                gh_api("repos/%s/rulesets/%s" % (repository, ruleset["id"]), "DELETE")
            except GitHubError as error:
                report.line("未通过", "规则集 %s" % describe_ruleset(ruleset), "移除失败：%s" % error.message)
                continue
            report.wrote("已移除", "规则集 %s" % describe_ruleset(ruleset), "它作用于默认分支 %s，由 %s 取代" % (branch, OURS))
    return ours_in_place


def apply_branch_protection(report, facts, ours_in_place):
    report.section("经典分支保护")
    path = "repos/%s/branches/%s/protection" % (facts["repository"], quote(facts["branch"], safe=""))
    subject = "%s 的经典分支保护" % facts["branch"]
    try:
        gh_api(path)
    except GitHubError as error:
        if error.status == 404:
            report.line("已就位", subject, "没有经典分支保护")
            return
        report.line("未通过", subject, "读取失败：%s" % error.message)
        return
    if not ours_in_place:
        report.line("已跳过", subject, "%s 未全部就位，先不移除" % OURS)
        return
    try:
        gh_api(path, "DELETE")
    except GitHubError as error:
        report.line("未通过", subject, "移除失败：%s" % error.message)
        return
    report.wrote("已移除", subject, "由 %s 取代" % OURS)


# 3. Settings, and 4's secret protection: both are fields of PATCH /repos/{owner}/{repo}.
# Each item is (subject, {path: value}), a path being the keys into the repository's JSON.

SETTINGS = (
    ("仅 squash 合并", {("allow_squash_merge",): True, ("allow_merge_commit",): False, ("allow_rebase_merge",): False}),
    ("合并后删除 head 分支", {("delete_branch_on_merge",): True}),
    ("auto-merge 关闭", {("allow_auto_merge",): False}),
)
SECRET_PROTECTION = tuple(
    (subject, {("security_and_analysis", key, "status"): "enabled"})
    for subject, key in (("secret scanning", "secret_scanning"), ("push protection", "secret_scanning_push_protection"))
)
PRIVATE_SECRET_REASON = "私有仓库：个人账户的私有仓库用不了 secret scanning 和 push protection（需要组织的 GitHub Secret Protection），按目标状态跳过"


def _at(data, path):
    for key in path:
        data = data.get(key) if isinstance(data, dict) else None
    return data


def _nested(pairs):
    body = {}
    for path, value in pairs:
        node = body
        for key in path[:-1]:
            node = node.setdefault(key, {})
        node[path[-1]] = value
    return body


def patch_repository(report, facts, items, in_place, done):
    """Write the items' differing fields in one PATCH and report each item from GitHub's answer."""
    differing = [(path, value) for _, values in items for path, value in values.items() if _at(facts["repo"], path) != value]
    written, failure = None, None
    if differing:
        try:
            written = gh_api("repos/%s" % facts["repository"], "PATCH", _nested(differing))
        except GitHubError as error:
            failure = error.message
    changed = set(path for path, _ in differing)
    for subject, values in items:
        if not changed.intersection(values):
            report.line("已就位", subject, in_place)
        elif failure is not None:
            report.line("未通过", subject, "GitHub 拒绝了写入：%s" % failure)
        elif all(_at(written, path) == value for path, value in values.items()):
            report.wrote("已设置", subject, done)
        else:
            report.line("未通过", subject, "GitHub 的回应仍不是目标值")


def apply_settings(report, facts):
    report.section("设置")
    patch_repository(report, facts, SETTINGS, "已是目标值", "已改为目标值")
    actions_cannot_approve(report, facts["repository"])


def actions_cannot_approve(report, repository):
    """The setting the agent can't read: Actions may not create or approve pull requests."""
    subject = "Actions 不能创建或批准 PR"
    path = "repos/%s/actions/permissions/workflow" % repository
    current = gh_api(path)
    if (not isinstance(current, dict)
            or current.get("default_workflow_permissions") not in ("read", "write")
            or type(current.get("can_approve_pull_request_reviews")) is not bool):
        report.line("未通过", subject, "工作流权限读取结果无效；保留现状，未写入此设置")
        return
    if current.get("can_approve_pull_request_reviews") is False:
        report.line("已就位", subject, "已关闭")
        return
    try:
        gh_api(path, "PUT", {
            "default_workflow_permissions": current["default_workflow_permissions"],
            "can_approve_pull_request_reviews": False,
        })
    except GitHubError as error:
        report.line("未通过", subject, "GitHub 拒绝了写入：%s" % error.message)
        return
    # Observe only: never repeat the accepted PUT. A changed default or malformed object
    # is not assumed to be transient. Bound both observation count and each read below.
    for attempt in range(3):
        if attempt:
            time.sleep(2)
        try:
            after = gh_api(path, timeout=5)
        except GitHubError:
            continue
        if (not isinstance(after, dict)
                or after.get("default_workflow_permissions") != current["default_workflow_permissions"]
                or type(after.get("can_approve_pull_request_reviews")) is not bool):
            report.wrote("未通过", subject, "GitHub 已接受写入，但读回默认权限变化或状态无效；停止核验，请核查")
            return
        if after["can_approve_pull_request_reviews"] is False:
            report.wrote("已设置", subject, "第 %d 次读回确认：默认工作流权限保持不变，审批已关闭" % (attempt + 1))
            return
    report.wrote("未通过", subject, "GitHub 已接受写入，但 3 次读回仍未确认审批关闭；停止核验，请核查")


# 4. Secret protection and the Actions event policy, public repositories only.


def apply_secret_protection(report, facts):
    report.section("Secret 保护")
    if facts["repo"].get("private"):
        for subject, _ in SECRET_PROTECTION:
            report.line("已跳过", subject, PRIVATE_SECRET_REASON)
        return
    patch_repository(report, facts, SECRET_PROTECTION, "已启用", "已启用")


# From 2026-12-02 GitHub's default policy blocks pull_request_target on a public repository
# without an applicable event policy, so the gate would never run. The policy allows that one
# event for the gate's workflow only; event rules are allowlists.
EVENT_POLICY = {
    "name": gate.CHECK,
    "enforcement": "active",
    "conditions": {"workflow_path": {"include": [GATE_WORKFLOW], "exclude": []}},
    "rules": [{"type": "restrict_action_events", "parameters": {"allowed_events": ["pull_request_target"]}}],
}
EVENT_POLICY_SUBJECT = "pull_request_target 事件策略"
EVENT_POLICY_BY_HAND = (
    "请在 Settings → Actions → Policies 手动设一次：新建一条 active 的策略，只针对 %s，事件只允许 pull_request_target；"
    "设好后重新运行本脚本确认" % GATE_WORKFLOW
)


def declared_policy(policy):
    """What the target declares about an event policy, from a body or GitHub's response; the name aside."""
    workflow_path = (policy.get("conditions") or {}).get("workflow_path") or {}
    rules = dict(
        (rule.get("type"), sorted((rule.get("parameters") or {}).get("allowed_events") or [])) for rule in policy.get("rules") or []
    )
    return {
        "enforcement": policy.get("enforcement"),
        "include": sorted(workflow_path.get("include") or ["~ALL"]),
        "exclude": sorted(workflow_path.get("exclude") or []),
        "rules": rules,
    }


def apply_event_policy(report, facts):
    report.section("Actions 事件策略")
    repository = facts["repository"]
    if facts["repo"].get("private"):
        report.line("已跳过", EVENT_POLICY_SUBJECT, "私有仓库：GitHub 默认拦截 pull_request_target 的策略只作用于公开仓库，按目标状态跳过")
        return
    try:
        listed = gh_api("repos/%s/actions/policies?has_parents=false&per_page=100" % repository) or {}
        policies = [
            gh_api("repos/%s/actions/policies/%s" % (repository, item["id"]))
            for item in listed.get("policies") or []
            if item.get("source_type", "Repository") == "Repository"
        ]
    except GitHubError as error:
        report.line("缺失", EVENT_POLICY_SUBJECT, "GitHub 的 API 读不到此仓库的事件策略（%s）；%s" % (error.message, EVENT_POLICY_BY_HAND))
        return
    wanted = declared_policy(EVENT_POLICY)
    ours = [policy for policy in policies if policy.get("name") == EVENT_POLICY["name"]]
    matching = [policy for policy in policies if declared_policy(policy) == wanted]
    for policy in policies:
        if policy not in matching and policy not in ours:
            report.line("已保留", "事件策略“%s”（id %s）" % (policy.get("name"), policy.get("id")), "不是本脚本声明的策略，保留不动")
    if matching:
        named = matching[0]
        report.line("已就位", EVENT_POLICY_SUBJECT, "策略“%s”只允许 %s 由 pull_request_target 触发" % (named.get("name"), GATE_WORKFLOW))
        return
    try:
        if ours:
            written = gh_api("repos/%s/actions/policies/%s" % (repository, ours[0]["id"]), "PUT", EVENT_POLICY)
        else:
            written = gh_api("repos/%s/actions/policies" % repository, "POST", EVENT_POLICY)
    except GitHubError as error:
        report.line("缺失", EVENT_POLICY_SUBJECT, "GitHub 的 API 没能写入（%s）；%s" % (error.message, EVENT_POLICY_BY_HAND))
        return
    if declared_policy(written or {}) != wanted:
        report.line("缺失", EVENT_POLICY_SUBJECT, "GitHub 的回应与目标不一致；%s" % EVENT_POLICY_BY_HAND)
        return
    report.wrote("已设置", EVENT_POLICY_SUBJECT, ("已更新" if ours else "已创建") + "：策略“%s”只允许 %s 由 pull_request_target 触发" % (EVENT_POLICY["name"], GATE_WORKFLOW))


def main():
    report = Report()
    try:
        facts = preconditions(report)
        ours_in_place = apply_rulesets(report, facts)
        apply_branch_protection(report, facts, ours_in_place)
        apply_settings(report, facts)
        apply_secret_protection(report, facts)
        apply_event_policy(report, facts)
    except (Stop, GitHubError) as error:
        reason = error.message if isinstance(error, GitHubError) else str(error)
        if not report.writes:
            report.line("未通过", report.current, "%s；未写入任何内容" % reason)
            return 2
        report.line("未通过", report.current, "%s；本次已写入 %d 项，其余未做，修好后重新运行" % (reason, report.writes))
        return 1
    report.section("结果")
    if report.problems:
        print("写入 %d 项；%d 项未通过或缺失，见上方各行" % (report.writes, report.problems))
        return 1
    print("写入 %d 项；全部就位" % report.writes if report.writes else "写入 0 项；全部已就位，本次未改动 GitHub")
    return 0


sys.exit(main())
